    try:
        import psutil
        available_memory = psutil.virtual_memory().available
        safe_memory = available_memory * 0.25
        rows_per_chunk = int(safe_memory / 200)
        return max(10000, min(200000, rows_per_chunk))
    except:
        return 50000

