import csv, json, re, queue, tempfile, subprocess, base64, zlib, unicodedata
from collections import Counter
from functools import lru_cache
NAME_DB = json.loads(zlib.decompress(base64.b85decode(_NAME_DB_B85)).decode('utf-8'))
MALE_NAMES = {k for k,v in NAME_DB.items() if v == '男'}
FEMALE_NAMES = {k for k,v in NAME_DB.items() if v == '女'}
NEUTRAL_NAMES = {k for k,v in NAME_DB.items() if v == '中性'}
SUPPORTED = '*.csv *.tsv *.txt *.xlsx *.xls *.xlsm *.xlsb *.ods *.docx *.json *.jsonl *.ndjson *.html *.htm *.pdf'
HEADERS = {'name','fullname','firstname','givenname','姓名','名字','全名','名'}

def name_key(value):
    return unicodedata.normalize('NFC', value).upper()

@lru_cache(maxsize=100000)
def extract_given_name(value, order='自动'):
    if not isinstance(value,str) or not value.strip(): return ''
    s = value.strip()
    if order == '姓, 名' or (order == '自动' and ',' in s):
        if ',' in s: s = s.split(',',1)[1].strip()
    tokens = s.split()
    while tokens and tokens[0].strip('.').lower() in {'mr','mrs','ms','miss','dr','prof','sir','rev'}:
        tokens.pop(0)
    if not tokens:return ''
    if order == '姓在前（空格）' and len(tokens)>1: tokens = tokens[1:]
    token=tokens[0].strip('.,;:()[]"')
    if len(token.strip('.'))<=1 or re.fullmatch(r'(?:[A-Za-z]\.){1,3}',token):return ''
    return name_key(token)

@lru_cache(maxsize=100000)
def predict_gender(name, order='自动'):
    key=extract_given_name(name,order)
    if not key:return '未知'
    return NAME_DB.get(key,'未知')

def detect_encoding(filepath):
    with open(filepath,'rb') as f: sample=f.read(131072)
    if sample.startswith(b'\xef\xbb\xbf'):return 'utf-8-sig'
    if sample.startswith((b'\xff\xfe',b'\xfe\xff')):return 'utf-16'
    for enc in ('utf-8','gb18030','cp1252'):
        try: sample.decode(enc);return enc
        except UnicodeDecodeError:pass
    raise ValueError('无法识别文本编码，请先另存为 UTF-8。')

def header_key(x):return re.sub(r'[ _\-]','',str(x)).lower()

def find_name_column(df):
    cols=list(df.columns)
    for c in cols:
        if header_key(c) in HEADERS:return c
    scores={c:sum(predict_gender(str(x))!='未知' for x in df[c].head(100)) for c in cols}
    return max(cols,key=lambda c:scores[c]) if cols else None

def has_header(row, mode):
    if mode=='有表头':return True
    if mode=='无表头':return False
    return any(header_key(x) in HEADERS for x in row)

class HeaderRow(list):pass

def table_rows(path, header_mode='自动'):
    ext=os.path.splitext(path)[1].lower()
    if ext in {'.csv','.tsv','.txt'}:
        enc=detect_encoding(path)
        with open(path,encoding=enc,newline='') as f:
            sample=f.read(16384);f.seek(0)
            delimiter='\t' if ext=='.tsv' else None
            if ext=='.csv':
                try:delimiter=csv.Sniffer().sniff(sample,delimiters=',;\t|').delimiter
                except csv.Error:delimiter=','
            elif ext=='.txt':
                # A plain list keeps each full name intact, including surname commas.
                if '\t' in sample:delimiter='\t'
            records=csv.reader(f,delimiter=delimiter) if delimiter else ([line.rstrip('\r\n')] for line in f)
            yield '数据',records
    elif ext in {'.xlsx','.xlsm'}:
        import openpyxl
        wb=openpyxl.load_workbook(path,read_only=True,data_only=True)
        try:
            for ws in wb.worksheets:
                yield ws.title,([str(x) if x is not None else '' for x in row] for row in ws.iter_rows(values_only=True))
        finally:wb.close()
    elif ext in {'.xls','.xlsb','.ods'}:
        engine={'.xls':'xlrd','.xlsb':'pyxlsb','.ods':'odf'}[ext]
        with pd.ExcelFile(path,engine=engine) as book:
            for sheet in book.sheet_names:
                df=pd.read_excel(book,sheet_name=sheet,header=None,dtype=str,keep_default_na=False)
                yield sheet, (list(row) for row in df.itertuples(index=False,name=None))
    elif ext=='.docx':
        from docx import Document
        from docx.oxml.ns import qn
        from docx.table import Table
        from docx.text.paragraph import Paragraph
        doc=Document(path)
        def rows():
            for el in doc.element.body:
                if el.tag==qn('w:p'):
                    p=Paragraph(el,doc).text
                    if p.strip():yield [p]
                elif el.tag==qn('w:tbl'):
                    for r in Table(el,doc).rows:yield [c.text for c in r.cells]
        yield '文档',rows()
    elif ext in {'.json','.jsonl','.ndjson'}:
        with open(path,encoding=detect_encoding(path)) as f:
            items=json.load(f) if ext=='.json' else [json.loads(x) for x in f if x.strip()]
        if isinstance(items,dict):
            if isinstance(items.get('data'),list):items=items['data']
            else:items=[items]
        if not isinstance(items,list):raise ValueError('JSON 必须是数组、对象，或含 data 数组的对象。')
        if all(isinstance(x,dict) for x in items):
            cols=list(dict.fromkeys(k for x in items for k in x))
            def cell(x):return json.dumps(x,ensure_ascii=False) if isinstance(x,(list,dict)) else ('' if x is None else str(x))
            yield 'JSON',iter([HeaderRow(cols)]+[[cell(x.get(c)) for c in cols] for x in items])
        elif all(isinstance(x,str) for x in items):yield 'JSON',([x] for x in items)
        else:raise ValueError('JSON 数组元素应统一为对象或姓名字符串。')
    elif ext in {'.html','.htm'}:
        tables=pd.read_html(path,keep_default_na=False)
        for i,df in enumerate(tables):yield f'表格{i+1}',iter([list(map(str,df.columns))]+df.astype(str).values.tolist())
    elif ext=='.pdf':
        from pypdf import PdfReader
        def rows():
            found=False
            for page in PdfReader(path).pages:
                text=page.extract_text() or ''
                for line in text.splitlines():
                    if line.strip():found=True;yield [line]
            if not found:raise ValueError('PDF 无可提取文字；扫描件请先做 OCR。')
        yield 'PDF文本行',rows()
    else:raise ValueError('不支持此格式。旧版 .doc 请另存为 .docx；图片请先做 OCR。')

def choose_column(headers, sample, name_col):
    if name_col:
        if name_col in headers:return headers.index(name_col)
        if name_col.isdigit():
            i=int(name_col)-1
        elif re.fullmatch('[A-Za-z]{1,3}',name_col):
            i=0
            for c in name_col.upper():i=i*26+ord(c)-64
            i-=1
        else:raise ValueError('找不到指定姓名列：'+name_col)
        if not 0<=i<len(headers):raise ValueError('姓名列超出列范围')
        return i
    for i,c in enumerate(headers):
        if header_key(c) in HEADERS:return i
    scores=[sum(predict_gender(str(r[i]))!='未知' for r in sample if i<len(r)) for i in range(len(headers))]
    return max(range(len(headers)),key=lambda i:scores[i]) if headers else 0

class Cancelled(Exception):pass

def process_file_gui(input_file,output_file,name_col,chunk_size,callback,stop_event=None,header_mode='自动',order='自动',filter_mode='全部',details=False):
    import itertools
    stop_event=stop_event or threading.Event()
    temp=None
    try:
        if os.path.realpath(input_file)==os.path.realpath(output_file):raise ValueError('输出文件不能覆盖输入文件。')
        ext=os.path.splitext(output_file)[1].lower()
        if ext not in {'.csv','.tsv','.txt','.jsonl','.xlsx'}:raise ValueError('输出支持 CSV / TSV / TXT / JSONL / XLSX。')
        os.makedirs(os.path.dirname(os.path.abspath(output_file)),exist_ok=True)
        fd,temp=tempfile.mkstemp(prefix='.gender_',suffix=ext,dir=os.path.dirname(os.path.abspath(output_file)));os.close(fd)
        counts=Counter();processed=written=0;started=time.monotonic();stamp=datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        callback('info','按姓名常见用法标注，不能确认本人实际性别；保留重复、顺序及原始姓名。')
        xbook=None
        if ext=='.xlsx':
            import openpyxl
            xbook=openpyxl.Workbook(write_only=True)
        with open(temp,'w',encoding='utf-8-sig' if ext!='.jsonl' else 'utf-8',newline='') as output:
            writer=csv.writer(output,delimiter='\t' if ext in {'.tsv','.txt'} else ',')
            for sheet,records in table_rows(input_file,header_mode):
                if stop_event.is_set():raise Cancelled()
                records=iter(records);sample=list(itertools.islice(records,100))
                if not sample:continue
                mode='有表头' if isinstance(sample[0],HeaderRow) else header_mode
                header=has_header(sample[0],mode)
                width=max(len(r) for r in sample)
                headers=list(sample[0]) if header else [f'列{i+1}' for i in range(width)]
                headers+=['']*(width-len(headers))
                rows=itertools.chain(sample[1:] if header else sample,records)
                idx=choose_column(headers,sample[1:] if header else sample,name_col)
                callback('info',f'{sheet}：姓名列 {idx+1} / {headers[idx]}；'+('有表头' if header else '无表头，首行保留'))
                def unique_col(base):
                    k=base;i=2
                    while k in headers:k=f'{base}_{i}';i+=1
                    return k
                result_headers=headers+[unique_col('性别'),unique_col('处理时间')]
                if details:result_headers += [unique_col('识别名字'),unique_col('依据')]
                ws=xbook.create_sheet(sheet[:31]) if xbook else None
                sheet_written=0
                # CSV/TSV: one header per table; TXT contains names only for filtering.
                if ws:ws.append(result_headers)
                elif ext not in {'.txt','.jsonl'}:writer.writerow(result_headers)
                for row in rows:
                    if stop_event.is_set():raise Cancelled()
                    row=list(row);name=row[idx] if idx<len(row) else '';label=predict_gender(name,order)
                    processed+=1;counts[label]+=1
                    keep=filter_mode=='全部' or filter_mode==label or (filter_mode=='男+中性+未知' and label!='女')
                    if keep:
                        if len(row)>len(headers):raise ValueError('检测到列数不一致的记录，请先将文档整理为固定列数表格。')
                        enriched=row+['']*(len(headers)-len(row))+[label,stamp]
                        if details:enriched += [extract_given_name(name,order),'姓名词库常见用法，非本人性别确认']
                        if ws:
                            if written and sheet_written>=1048575:raise ValueError('工作表超过 Excel 行数上限，请改用 CSV。')
                            ws.append(enriched);sheet_written+=1
                        elif ext=='.txt':output.write(str(name)+'\n')
                        elif ext=='.jsonl':output.write(json.dumps({'sheet':sheet,'columns':headers,'values':row,'姓名用法':label,'处理时间':stamp},ensure_ascii=False)+'\n')
                        else:writer.writerow(enriched)
                        written+=1
                    if processed%1000==0:
                        callback('stats',*[counts[x] for x in ['男','女','中性','未知']])
                        callback('progress',0,f'已处理 {processed:,} 行，输出 {written:,} 行；{processed/max(.001,time.monotonic()-started):.0f} 行/秒')
                    if processed%chunk_size==0:gc.collect()
        if stop_event.is_set():raise Cancelled()
        if xbook:xbook.save(temp)
        os.replace(temp,output_file);temp=None
        callback('stats',*[counts[x] for x in ['男','女','中性','未知']])
        callback('progress',100,f'完成：输入 {processed:,} 行 / 输出 {written:,} 行')
        callback('info',f'完成：输入 {processed:,} 行，输出 {written:,} 行；筛选：{filter_mode}。输出 {output_file}')
        callback('done',None)
    except Cancelled:callback('cancelled',None)
    except ImportError as e:callback('error',f'缺少读取此格式的依赖：{e}。请运行安装依赖.bat。')
    except Exception as e:callback('error',str(e))
    finally:
        if temp and os.path.exists(temp):os.remove(temp)

OriginalGenderApp=GenderApp
class GenderApp(OriginalGenderApp):
    def __init__(self,root):
        self.events=queue.Queue();self.stop_event=threading.Event()
        super().__init__(root)
        root.geometry('1050x920')
        options=ttk.LabelFrame(root,text='新增：全名识别 / 文档设置 / 分类筛选',padding=8)
        options.pack(side=tk.BOTTOM,fill=tk.X,padx=15,pady=8)
        self.header_mode=tk.StringVar(value='自动');self.name_order=tk.StringVar(value='自动');self.filter_mode=tk.StringVar(value='全部');self.details=tk.BooleanVar(value=False)
        for title,var,values in [('表头',self.header_mode,['自动','有表头','无表头']),('姓名顺序',self.name_order,['自动','名在前','姓, 名','姓在前（空格）']),('输出筛选',self.filter_mode,['全部','男','女','中性','未知','男+中性+未知'])]:
            ttk.Label(options,text=title).pack(side=tk.LEFT,padx=4)
            ttk.Combobox(options,textvariable=var,values=values,state='readonly',width=17).pack(side=tk.LEFT)
        ttk.Checkbutton(options,text='附识别依据',variable=self.details).pack(side=tk.LEFT,padx=6)
        self.log('info',f'真实去重名字库：{len(NAME_DB):,}；TXT 输出为单列姓名，CSV 等保留全部字段。')
        self.log('info','姓名列支持列名 / A、B、C / 1、2、3；表头不明确时请手动选。')
        self.root.after(100,self.drain_events)
    def drain_events(self):
        for _ in range(80):
            try:t,args=self.events.get_nowait()
            except queue.Empty:break
            if t=='stats':self.update_stats(*args)
            elif t=='cancelled':
                self.is_running=False;self.start_btn.config(state=tk.NORMAL);self.stop_btn.config(state=tk.DISABLED)
                self.status_label.config(text='已停止');self.log('warning','已停止，未覆盖原有输出文件。')
            else:super().callback_handler(t,*args)
        self.root.after(100,self.drain_events)
    def callback_handler(self,type_,*args):self.events.put((type_,args))
    def log(self,level,message):
        self.log_text.insert(tk.END,f'[{datetime.now():%H:%M:%S}] {message}\n',level)
        if int(self.log_text.index('end-1c').split('.')[0])>500:self.log_text.delete('1.0','100.0')
        self.log_text.see(tk.END)
    def select_input(self):
        path=filedialog.askopenfilename(title='选择文档',filetypes=[('支持的文档',SUPPORTED),('所有文件','*.*')])
        if path:self.input_path.set(path);self.output_path.set(os.path.splitext(path)[0]+'_性别结果.csv')
    def select_output(self):
        path=filedialog.asksaveasfilename(defaultextension='.csv',filetypes=[('CSV','.csv'),('单列姓名 TXT','.txt'),('TSV','.tsv'),('Excel','.xlsx'),('JSONL','.jsonl')])
        if path:self.output_path.set(path)
    def start_processing(self):
        if self.is_running:return
        inp=self.input_path.get().strip();out=self.output_path.get().strip()
        if not os.path.isfile(inp) or not out:messagebox.showerror('提示','请选择有效输入文件和输出路径。');return
        if os.path.realpath(inp)==os.path.realpath(out):messagebox.showerror('提示','输出不能覆盖输入文件。');return
        try:chunk=max(5000,min(500000,int(self.chunk_size.get())))
        except Exception:messagebox.showerror('提示','批次大小必须为整数。');return
        self.stop_event.clear();self.is_running=True
        self.start_btn.config(state=tk.DISABLED);self.stop_btn.config(state=tk.NORMAL)
        self.update_stats(0,0,0,0);self.progress_var.set(0);self.status_label.config(text='处理中…')
        args=(inp,out,self.col_name.get().strip(),chunk,self.callback_handler,self.stop_event,self.header_mode.get(),self.name_order.get(),self.filter_mode.get(),self.details.get())
        self.processing_thread=threading.Thread(target=process_file_gui,args=args,daemon=True);self.processing_thread.start()
    def stop_processing(self):
        if self.is_running:self.stop_event.set();self.stop_btn.config(state=tk.DISABLED);self.status_label.config(text='正在停止…')
    def open_output_dir(self):
        path=os.path.dirname(os.path.abspath(self.output_path.get()))
        if os.path.isdir(path):
            if sys.platform=='win32':os.startfile(path)
            else:subprocess.Popen(['open' if sys.platform=='darwin' else 'xdg-open',path])
    def show_help(self):
        messagebox.showinfo('使用说明','输入：CSV / TSV / TXT / XLSX / XLS / XLSM / XLSB / ODS / DOCX / JSON / JSONL / HTML表格 / 文字PDF。\n输出：CSV / TSV / TXT单列姓名 / JSONL / XLSX。\n默认全部保留，选择筛选后才剔除其他类别；不去重、不改姓名。\n全名支持名在前、姓在前及姓, 名；不根据姓氏猜测。\n姓名列可填列名、列字母或从1开始的列号。\n自动表头只认常见姓名列标题，不明确请手动选择。\nExcel读取全部工作表，CSV/TSV用分段表头区分表；XLSX分别保存工作表。\nDOCX读取正文段落及表格；PDF每个非空文本行为一条，复杂排版先转表格，扫描件需OCR。\n名字库为常见用法词库，不能确认实际性别；中性/未知保持标注。\n停止会删除临时输出，不覆盖之前结果。')
    def on_closing(self):
        if self.is_running and not messagebox.askokcancel('确认','处理正在进行，退出会取消本次输出，确定退出？'):return
        self.stop_event.set();self.root.destroy()

if __name__=='__main__':
    root=tk.Tk();app=GenderApp(root);root.mainloop()
